def count_calls(func):
    def wrapper(*args, **kwargs):
        wrapper.calls += 1
        return func(*args, **kwargs)
    wrapper.calls = 0
    return wrapper

tests.code:
@count_calls
def add(a, b=0):
    return a + b
assert add(1, b=2) == 3, 'The wrapper should pass keyword arguments through.'

